/bin/bash -c "python3 -I -S - <<'PY'
import json
p = open('PROMPT.md').read()
d = json.loads(p[p.index('{\\n  \"input\"'):])
def outline(x, path='', depth=0):
    if depth > 4: return
    if isinstance(x, dict):
        for k,v in x.items():
            q = path + '.' + k
            if isinstance(v, (dict,list)): print(q, type(v).__name__,len(v)); outline(v,q,depth+1)
            elif isinstance(v,str): print(q, 'str', len(v), repr(v[:120]))
            else: print(q, repr(v))
    elif isinstance(x,list):
        for i,v in enumerate(x):
            if isinstance(v,dict): print(path+f'[{i}]', list(v))
outline(d['input'])
